//! Support for code generated by the derive macros. Not a public API.

pub use crate::Decoder;
use crate::{Decode, DecodeError};

pub use std::any::type_name;
pub use std::result::Result::{self, Err, Ok};

/// An envelope's header: version, compat version, body size.
pub const ENVELOPE_HEADER_LEN: usize = 6;

/// Writes an envelope whose body is whatever `body` appends.
///
/// The size is patched in after the body is written, as Redpanda does, so
/// encoding doesn't depend on `encoded_len` being right.
pub fn encode_envelope(
    buf: &mut Vec<u8>,
    version: u8,
    compat_version: u8,
    body: impl FnOnce(&mut Vec<u8>),
) {
    buf.push(version);
    buf.push(compat_version);
    let size_at = buf.len();
    buf.extend_from_slice(&0u32.to_le_bytes());
    body(buf);
    let size = buf.len() - size_at - 4;
    let size = u32::try_from(size).expect("shep-codec: envelope body exceeds u32::MAX bytes");
    buf[size_at..size_at + 4].copy_from_slice(&size.to_le_bytes());
}

/// Reads an envelope's header, checks that a reader at `version` /
/// `compat_version` may read it, and runs `body` on its body alone, one level
/// of nesting deeper.
///
/// Decoding fields in `body` can't read past the envelope, and whatever they
/// leave of it is skipped.
pub fn decode_envelope<T>(
    d: &mut Decoder<'_>,
    type_name: &'static str,
    version: u8,
    compat_version: u8,
    body: impl FnOnce(&mut Decoder<'_>) -> Result<T, DecodeError>,
) -> Result<T, DecodeError> {
    d.nested(|d| {
        let data_version = u8::decode(d)?;
        let data_compat_version = u8::decode(d)?;
        let size = u32::decode(d)? as usize;
        if d.remaining() < size {
            return Err(DecodeError::UnexpectedEnd {
                needed: size,
                remaining: d.remaining(),
            });
        }
        if data_compat_version > version || data_version < compat_version {
            return Err(DecodeError::IncompatibleVersion {
                type_name,
                version: data_version,
                compat_version: data_compat_version,
                reader_version: version,
                reader_compat_version: compat_version,
            });
        }
        d.within(size, body)
    })
}

/// Decodes a transparent newtype's field, one level of nesting deeper.
pub fn decode_transparent<T: Decode>(d: &mut Decoder<'_>) -> Result<T, DecodeError> {
    d.nested(T::decode)
}

/// Decodes a field that old data must contain. One that encodes to nothing,
/// like `[u8; 0]`, is there even when the body is used up.
pub fn decode_field<T: Decode>(
    d: &mut Decoder<'_>,
    type_name: &'static str,
    field: &'static str,
) -> Result<T, DecodeError> {
    if d.is_empty() {
        return T::decode(d).map_err(|_| DecodeError::MissingField { type_name, field });
    }
    T::decode(d)
}

/// Decodes a `#[codec(default)]` field, which old data may lack.
pub fn decode_field_or_default<T: Decode + Default>(d: &mut Decoder<'_>) -> Result<T, DecodeError> {
    if d.is_empty() {
        return Ok(T::default());
    }
    T::decode(d)
}
